package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.workflow.TaskRunStageProtocolV2.FieldCompletionV2;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;

/** Historical proof only: no lease claim, token, source read, approval, or producer call is reachable. */
public final class TaskStrictFieldOriginalResult {
    private final TaskStrictFieldOutputLedger outputs;private final JdbcTemplate db;private final TaskStrictFieldSchema schema;private final StrictFieldComparisonSchema comparison;private final StrictComparisonStore policies;private final StrictComparisonCodec codec;private final StrictFieldComparisonEngine.Limits limits;
    TaskStrictFieldOriginalResult(DataSource data,TaskStrictFieldSchema schema,StrictFieldComparisonSchema comparison,StrictComparisonStore policies,StrictComparisonCodec codec,TaskStrictFieldRuntimePolicy capacity,TaskStrictFieldOutputLedger outputs){this.outputs=outputs;db=new JdbcTemplate(data);db.setQueryTimeout(5);this.schema=schema;this.comparison=comparison;this.policies=policies;this.codec=codec;limits=capacity.limits();}
    Original require(EnterpriseAccess.Admission a,FieldCompletionV2 locator)throws Exception{
        if(!a.recoveryWorker())deny();a.recoveryProof().requireActive();var identity=a.recoveryProof().identity();if(!identity.runId().equals(locator.runId()))deny();return inspect(a,identity.projectId(),identity.taskId(),locator,()->a.recoveryProof().requireActive());
    }
    Original lifecycle(TaskRunLifecycleAuthority.Proof proof,FieldCompletionV2 locator)throws Exception{proof.require(proof.operation());if(!proof.reference().runId().equals(locator.runId()))deny();return inspect(proof.admission(),proof.reference().projectId(),proof.taskId(),locator,()->proof.require(proof.operation()));}
    Original consumer(TaskNodeProductionAuthority.Verified production,FieldCompletionV2 locator)throws Exception{production.requireUnchanged();if(!production.runId().equals(locator.runId()))deny();return inspect(production.admission(),production.projectId(),production.taskId(),locator,production::requireUnchanged);}
    Original consumer(TaskRunResumeOriginalAuthority.Source source,FieldCompletionV2 locator)throws Exception{
        source.requireOriginal(source.admission(),locator.runId(),locator.stepId());if(!"N03".equals(source.stageKind()))deny();var p=source.successor();
        return inspect(source.admission(),p.projectId(),p.taskId(),locator,source::requireUnchanged);
    }
    @FunctionalInterface private interface Guard{void require()throws Exception;}
    private Original inspect(EnterpriseAccess.Admission a,String project,String task,FieldCompletionV2 locator,Guard guard)throws Exception{
        guard.require();String tenant=a.context().tenant_id();var result=one(db.queryForList("SELECT * FROM task_strict_field_result WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND result_id=? LIMIT 2 FOR UPDATE",tenant,project,locator.runId(),locator.stepId(),locator.resultId()));
        var body=schema.read(str(result,"result_json"));var receipt=schema.read(str(result,"receipt_json"));if(!schema.hash(body).equals(locator.resultSha256())||!schema.hash(receipt).equals(str(result,"receipt_sha256"))||!locator.resultSha256().equals(str(result,"result_sha256"))||!a.actorId().equals(str(result,"created_by"))||!"FIELD_TARGET".equals(str(result,"target_kind"))||!"UNKNOWN".equals(body.required("professional_status").asText()))bad();
        for(var pin:Map.of("input_id",locator.inputId(),"input_sha256",locator.inputSha256(),"action_id",locator.actionId(),"lease_generation",Long.toString(locator.leaseGeneration()),"result_id",locator.resultId(),"result_sha256",locator.resultSha256()).entrySet())if(!pin.getValue().equals(str(result,pin.getKey()))||!pin.getValue().equals(receipt.required(pin.getKey()).asText()))bad();
        var in=one(db.queryForList("SELECT * FROM task_strict_field_input WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND input_id=? LIMIT 2 FOR UPDATE",tenant,project,locator.runId(),locator.stepId(),locator.inputId()));var input=schema.input(str(in,"canonical_input").getBytes(java.nio.charset.StandardCharsets.UTF_8));var inputReceipt=schema.read(str(in,"receipt_json"));if(!task.equals(input.taskId())||!schema.hash(input).equals(locator.inputSha256())||!schema.hash(inputReceipt).equals(str(in,"receipt_sha256"))||!str(in,"receipt_sha256").equals(body.required("identity").required("input_receipt_sha256").asText())||!input.targetArtifactId().equals(body.required("target_artifact_id").asText())||!input.targetObject().sha256().equals(body.required("target_object_sha256").asText())||!input.targetRegistrationSha256().equals(body.required("target_registration_sha256").asText()))bad();
        journal(in,tenant,project,a.actorId(),locator.inputId(),locator.runId(),"task.strict_field.input.registered",inputReceipt,str(in,"audit_id"),str(in,"event_id"));
        if(!a.actorId().equals(body.required("identity").required("actor_id").asText()))bad();var action=schema.action(body.required("identity").required("action"));if(!locator.actionId().equals(action.actionId())||!locator.runId().equals(action.runId())||!locator.stepId().equals(action.stepId())||locator.leaseGeneration()!=action.generation().longValueExact()||!locator.inputSha256().equals(action.inputSha256())||!"TOOL".equals(action.kind())||!TaskStrictFieldNode.ACTION.equals(action.action())||!TaskStrictFieldNode.PURPOSE.equals(action.purpose())||!input.toolVersion().version_id().equals(action.toolVersion())||!new PermissionProtocol.Scope(tenant,project,"TASK",task).equals(action.scope()))bad();
        var args=body.required("identity").required("arguments");TaskStrictFieldNode.requireArguments(input,args);if(!schema.hash(args).equals(action.argumentsSha256()))bad();var binding=one(db.queryForList("SELECT * FROM step_action_binding WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND action_id=? LIMIT 2 FOR UPDATE",tenant,project,locator.runId(),locator.stepId(),locator.actionId()));for(var pin:Map.of("kind","TOOL","input_sha256",locator.inputSha256(),"arguments_sha256",action.argumentsSha256(),"tool_version",action.toolVersion(),"lease_generation",Long.toString(locator.leaseGeneration()),"created_by",a.actorId()).entrySet())if(!pin.getValue().equals(str(binding,pin.getKey())))bad();
        var target=schema.target(input);var request=comparison.request(body.required("request"));var requests=new HashMap<String,StrictFieldComparisonProtocol.EntryRequest>();for(var item:request.entries())if(requests.put(item.entryId(),item)!=null)bad();var sourceIds=new HashSet<String>();
        for(var pin:body.required("source_reads")){
            String entry=pin.required("entry_id").asText();if(!sourceIds.add(entry)||!requests.containsKey(entry))bad();var expected=requests.get(entry).sourceObservation();if(pin.required("receipt_id").isNull()){if(expected!=null||!pin.required("receipt_sha256").isNull())bad();
                var fixed=target.entries().stream().filter(x->x.entryId().equals(entry)).findFirst().orElseThrow();
                if(TaskStrictFieldTypedProtocol.typed(input.targetManifest().path("schema_ref").asText())||(fixed.provenance()!=null&&fixed.provenance().source()!=null&&"SOURCE_EXACT_REVISION".equals(fixed.provenance().source().kind())&&fixed.provenance().source().sourceExact()!=null))bad();
                if(!db.queryForList("SELECT receipt_id FROM task_strict_field_source_read WHERE tenant_id=? AND run_id=? AND step_id=? AND action_id=? AND lease_generation=? AND entry_id=?",tenant,locator.runId(),locator.stepId(),locator.actionId(),locator.leaseGeneration(),entry).isEmpty())bad();continue;}
            var source=one(db.queryForList("SELECT * FROM task_strict_field_source_read WHERE tenant_id=? AND receipt_id=? LIMIT 2 FOR UPDATE",tenant,pin.required("receipt_id").asText()));var read=schema.read(str(source,"receipt_json"));if(!schema.hash(read).equals(pin.required("receipt_sha256").asText())||!schema.hash(read).equals(str(source,"receipt_sha256"))||!body.required("identity").equals(read.required("identity"))||!entry.equals(read.required("entry_id").asText())||expected==null)bad();
            var observed=read.required("observation").deepCopy();var receipts=(com.fasterxml.jackson.databind.node.ArrayNode)observed.required("provenance").required("read_receipt_ids");receipts.add(pin.required("receipt_id").asText());if(!schema.tree(expected).equals(observed))bad();
            var audit=one(db.queryForList("SELECT * FROM audit_event WHERE tenant_id=? AND audit_id=? LIMIT 2 FOR UPDATE",tenant,str(source,"audit_id")));metadata(source,audit,tenant,project,a.actorId());for(var p:Map.of("run_id",locator.runId(),"step_id",locator.stepId(),"input_id",locator.inputId(),"input_sha256",locator.inputSha256(),"action_id",locator.actionId(),"lease_generation",Long.toString(locator.leaseGeneration()),"entry_id",entry).entrySet())if(!p.getValue().equals(str(source,p.getKey())))bad();if(!locator.runId().equals(str(audit,"trace_id")))bad();if(!"task.strict_field.source.read".equals(str(audit,"action"))||!"SUCCESS".equals(str(audit,"result"))||!a.actorId().equals(str(audit,"subject_id"))||!read.equals(schema.read(str(audit,"resource_ref")))||!pin.required("receipt_id").asText().equals(str(audit,"request_id")))bad();
        }
        if(!sourceIds.equals(requests.keySet()))bad();for(var selected:input.policies()){var actual=requests.get(selected.entryId());if(actual==null||!selected.policy().version_id().equals(actual.rule().ruleRevision())||!selected.policy().content_sha256().equals(actual.rule().ruleSha256()))bad();}var definitions=new ArrayList<TaskStrictFieldCheck.Policy>();var policyIds=new HashSet<String>();
        for(var pin:body.required("policies")){
            String id=pin.required("revision").asText();if(!policyIds.add(id))bad();var row=policies.read(a,project,StrictComparisonStore.Kind.POLICY,id);var decision=policies.read(a,project,StrictComparisonStore.Kind.DECISION,pin.required("decision_id").asText());
            if(!decision.digest().equals(pin.required("decision_sha256").asText())||!row.digest().equals(pin.required("digest").asText())||!row.body().required("definition").equals(pin.required("definition"))||!id.equals(decision.parentId())||!id.equals(decision.body().required("policy_revision").asText())||!row.digest().equals(decision.body().required("definition_sha256").asText())||!"APPROVED".equals(decision.body().required("status").asText())||!"APPROVE".equals(decision.body().required("decision").required("decision").asText())||row.receipt().required("created_by").equals(decision.receipt().required("created_by")))bad();definitions.add(new TaskStrictFieldCheck.Policy(id,row.digest(),codec.bind(pin.required("definition"),StrictComparisonPolicyDefinition.Definition.class)));
        }
        var evaluation=new TaskStrictFieldCheck(comparison,StrictComparisonPolicyService.implementation()).evaluate(target,request,definitions,limits);if(!schema.tree(evaluation).equals(body.required("evaluation"))||!evaluation.disposition().name().equals(body.required("disposition").asText()))bad();
        boolean satisfied=evaluation.disposition()==TaskStrictFieldCheck.Disposition.CHECKED&&evaluation.waitingEntries().isEmpty()&&evaluation.comparison()!=null&&evaluation.comparison().entries().size()==target.entries().size()&&evaluation.comparison().entries().stream().allMatch(e->e.outcome()==StrictFieldComparisonProtocol.Outcome.COMPUTED&&e.result()==ArtifactProtocol.ComparisonResult.MATCH);
        journal(result,tenant,project,a.actorId(),locator.resultId(),locator.runId(),"task.strict_field.result.registered",receipt,str(result,"audit_id"),str(result,"event_id"));var output=outputs.original(a,receipt);if(!locator.producerReceiptSha256().equals(output.receiptSha256()))bad();satisfied=satisfied&&output.content().missingRequirementIds().isEmpty()&&output.content().methodCoverage().stream().allMatch(m->m.result()==ArtifactProtocol.CoverageResult.COMPLETE);guard.require();return new Original(a,project,task,locator,guard,output.receipt(),satisfied);
    }
    public final class Original{
        private final EnterpriseAccess.Admission admission;private final String project,task;private final FieldCompletionV2 locator;private final Guard guard;private final JsonNode receipt;private final boolean satisfied;
        private Original(EnterpriseAccess.Admission a,String project,String task,FieldCompletionV2 locator,Guard guard,JsonNode receipt,boolean satisfied){admission=a;this.project=project;this.task=task;this.locator=locator;this.guard=guard;this.receipt=receipt.deepCopy();this.satisfied=satisfied;}
        public void requireUnchanged()throws Exception{var fresh=inspect(admission,project,task,locator,guard);if(!receipt.equals(fresh.receipt)||satisfied!=fresh.satisfied)bad();}
        public JsonNode receipt(){return receipt.deepCopy();}public String receiptSha256(){return locator.producerReceiptSha256();}public String resultSha256(){return locator.resultSha256();}public boolean stageSatisfied(){return satisfied;}
    }
    private void journal(Map<String,Object> row,String tenant,String project,String actor,String request,String trace,String action,JsonNode receipt,String audit,String event)throws Exception{var a=one(db.queryForList("SELECT * FROM audit_event WHERE tenant_id=? AND audit_id=? FOR UPDATE",tenant,audit));var e=one(db.queryForList("SELECT * FROM outbox_event WHERE tenant_id=? AND event_id=? FOR UPDATE",tenant,event));metadata(row,a,tenant,project,actor);if(!tenant.equals(str(e,"tenant_id"))||!event.equals(str(e,"event_id"))||!"1".equals(str(e,"aggregate_revision"))||!Objects.equals(row.get("created_at"),e.get("occurred_at")))bad();if(!project.equals(str(a,"project_id"))||!actor.equals(str(a,"subject_id"))||!request.equals(str(a,"request_id"))||!trace.equals(str(a,"trace_id"))||!action.equals(str(a,"action"))||!"SUCCESS".equals(str(a,"result"))||!receipt.equals(schema.read(str(a,"resource_ref")))||!action.equals(str(e,"event_type"))||!request.equals(str(e,"aggregate_id"))||!receipt.equals(schema.read(str(e,"payload"))))bad();}
    private void metadata(Map<String,Object> row,Map<String,Object> audit,String tenant,String project,String actor)throws Exception{
        for(var pin:Map.of("tenant_id",tenant,"project_id",project,"created_by",actor,"schema_version",row.containsKey("canonical_input")?schema.input(str(row,"canonical_input").getBytes(java.nio.charset.StandardCharsets.UTF_8)).schemaVersion():"1.0.0","schema_manifest_sha256",row.containsKey("canonical_input")?schema.manifest(schema.input(str(row,"canonical_input").getBytes(java.nio.charset.StandardCharsets.UTF_8)).schemaVersion()):schema.manifest()).entrySet())if(!pin.getValue().equals(str(row,pin.getKey()))||!pin.getValue().equals(str(audit,pin.getKey())))bad();
        if(!Objects.equals(row.get("created_at"),audit.get("created_at"))||!Objects.equals(row.get("classification"),audit.get("classification"))||audit.get("reason_code")!=null)bad();
    }
    private static String str(Map<String,Object> r,String k){return Objects.requireNonNull(r.get(k)).toString();}private static <T>T one(List<T> r){if(r.size()!=1)bad();return r.get(0);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
